mapper.select:
select


FROM
gc_user_access ua
LEFT JOIN gc_access a on ua.access_id=a.id
WHERE ua.master_id=#{masterId}

    AND ua.user_id=#{userId}

SELECT ua.user_id,ui.id as info_id,ui.first_name,ui.last_name, uae.log_in_time as lastLogInDate from gc_user_access_ext uae LEFT JOIN gc_user_access ua on uae.user_access_id=ua.id LEFT JOIN gc_user u on u.id=ua.user_id LEFT JOIN gc_user_info ui on ui.id=u.info_id WHERE 1=1
AND ua.user_id in
#{userId}
and master_id=#{masterId}
ORDER BY lastLogInDate asc
ORDER BY lastLogInDate desc

select count(id) from gc_user_access where master_id=#{masterId}
and user_id=#{userId}
and role_json::text like concat('%',#{role},'%')

SELECT ua.user_id, a.code, u.update_time, f.id as f_id, f.name as f_name, ui.id as info_id, ui.first_name, ui.last_name, u.create_time as dateSignedUp, per.sub_permission as sub_permission, ua.id as userAccessId, u.username as email, ui.avatar_file_id as f_file_url, f.save_type as f_save_type, COUNT(pay.id) as joinType, COUNT(DISTINCT a.master_id) as portalNums, STRING_AGG(DISTINCT concat(a.master_id, ':', ma.portal_name), ',') AS userPortals, ua.access_id as accessId FROM gc_user_access ua LEFT JOIN gc_access a ON ua.access_id = a.id LEFT JOIN gc_user_access_permission per ON per.user_access_id = ua.id LEFT JOIN gc_master ma ON ma.id = a.master_id JOIN gc_user u ON ua.user_id = u.id LEFT JOIN gc_user_info ui ON ui.id = u.info_id LEFT JOIN sys_file f ON ui.avatar_file_id = f.id LEFT JOIN sys_weixin_pay pay ON pay.access_id = a.id AND a.master_id = pay.master_id AND order_status = 1 WHERE 1 = 1
AND ua.master_id IN
#{masterId}
AND a.id = #{accessId}
AND REPLACE(CONCAT_WS(',', CONCAT(ui.first_name, ui.last_name), u.username, a.CODE), ' ', '') LIKE concat('%', #{searchFilter}, '%')
GROUP BY ua.user_id, a.code, ua.user_id, u.update_time, f.id, f.name, ui.id, ui.first_name, ui.last_name, u.create_time, per.sub_permission::jsonb, ua.id, u.username, ui.avatar_file_id, f.save_type, ua.access_id ORDER BY u.update_time DESC

select

    COUNT(CASE WHEN CURRENT_DATE - '#{lastday} day'::interval >= ua.create_time THEN TRUE END) as day_#{lastday}

from gc_user_access ua
LEFT JOIN gc_access a ON ua.access_id=a.id
WHERE
a.admin_id=#{teacherAccessId}

select
COUNT( CASE WHEN CURRENT_DATE - '#{lastday} day'::interval > uae.log_in_time AND CURRENT_DATE - '#{lastday + 30} day'::interval < uae.log_in_time THEN TRUE END ) as day_#{lastday}_30day, COUNT( CASE WHEN CURRENT_DATE - '#{lastday} day'::interval > uae.log_in_time AND CURRENT_DATE - '#{lastday + 7} day'::interval < uae.log_in_time THEN TRUE END ) as day_#{lastday}_7day, COUNT( CASE WHEN CURRENT_DATE - '#{lastday} day'::interval > uae.log_in_time AND CURRENT_DATE - '#{lastday + 1} day'::interval < uae.log_in_time THEN TRUE END ) as day_#{lastday}_1day
from gc_user_access_ext uae LEFT JOIN gc_user_access ua ON ua.id=uae.user_access_id LEFT JOIN gc_access a ON ua.access_id=a.id WHERE a.admin_id=#{teacherAccessId}

mapper.insert:
insert into gc_user_access (user_id,master_id,access_id,role_json,parent_code)
SELECT #{item.userId},#{item.masterId},#{item.accessId}, #{item.roleJson,jdbcType=OTHER,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler}, #{item.parentCode}
ON CONFLICT (user_id, master_id, access_id) DO UPDATE SET user_id = EXCLUDED.user_id, master_id = EXCLUDED.master_id, access_id = EXCLUDED.access_id, role_json = EXCLUDED.role_json, parent_code = EXCLUDED.parent_code

